package store

import (
	"database/sql"
	"time"
)

// Outcome status values mirror the public response codes.
const (
	StatusAcquired         = "ACQUIRED"
	StatusReentry          = "REENTRY"
	StatusWaiting          = "WAITING"
	StatusReleased         = "RELEASED"
	StatusReentryDecrement = "REENTRY_DECREMENTED"
)

// resourceRow is the mutable state of one resource row.
type resourceRow struct {
	ownerID        sql.NullString
	leaseExpiresAt sql.NullInt64
	reentryCount   int64
	expiredOwnerID sql.NullString
}

func (r resourceRow) hasOwner() bool { return r.ownerID.Valid }

func (r resourceRow) isExpired(now time.Time) bool {
	return r.ownerID.Valid && r.leaseExpiresAt.Valid &&
		now.UnixMilli() >= r.leaseExpiresAt.Int64
}

func readRow(q queryable, resourceID string) (resourceRow, error) {
	var row resourceRow
	err := q.QueryRow(
		`SELECT owner_id, lease_expires_at, reentry_count, expired_owner_id
		 FROM resources WHERE resource_id = ?`, resourceID,
	).Scan(&row.ownerID, &row.leaseExpiresAt, &row.reentryCount, &row.expiredOwnerID)
	return row, err
}

func isWaiting(q queryable, resourceID, ownerID string) (bool, error) {
	var count int
	err := q.QueryRow(
		`SELECT COUNT(1) FROM waiting_requests WHERE resource_id = ? AND owner_id = ?`,
		resourceID, ownerID,
	).Scan(&count)
	return count > 0, err
}

type queryable interface {
	QueryRow(query string, args ...any) *sql.Row
}
package store

import (
	"database/sql"
	"errors"
)

// Release frees one reentry of the current holder. The final reentry transfers the
// lock to the first waiter, or leaves the resource holderless.
func (s *Store) Release(resourceID, ownerID string) (Outcome, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return Outcome{}, err
	}
	defer tx.Rollback()

	now := s.nowTime()
	row, err := readRow(tx, resourceID)
	if errors.Is(err, sql.ErrNoRows) {
		return Outcome{}, ErrResourceNotFound
	}
	if err != nil {
		return Outcome{}, err
	}

	if row.hasOwner() && row.isExpired(now) && row.ownerID.String == ownerID {
		if err := promoteExpired(tx, resourceID, row, now); err != nil {
			return Outcome{}, err
		}
		if err := tx.Commit(); err != nil {
			return Outcome{}, err
		}
		return Outcome{}, ErrLeaseExpired
	}
	if !row.hasOwner() || row.ownerID.String != ownerID {
		if row.expiredOwnerID.Valid && row.expiredOwnerID.String == ownerID {
			return Outcome{}, ErrLeaseExpired
		}
		return Outcome{}, ErrNotOwner
	}

	status := StatusReleased
	if row.reentryCount > 1 {
		if _, err := tx.Exec(
			`UPDATE resources SET reentry_count = reentry_count - 1 WHERE resource_id = ?`,
			resourceID,
		); err != nil {
			return Outcome{}, err
		}
		status = StatusReentryDecrement
	} else {
		if err := promoteVoluntary(tx, resourceID, now); err != nil {
			return Outcome{}, err
		}
	}

	if err := tx.Commit(); err != nil {
		return Outcome{}, err
	}
	state, err := s.getStateLocked(resourceID)
	if err != nil {
		return Outcome{}, err
	}
	return Outcome{Status: status, State: state}, nil
}

// Reenter adds one reentry for the current holder. It never extends the lease and
// returns the same ownerId and leaseExpiresAt as the current holding.
func (s *Store) Reenter(resourceID, ownerID string) (Outcome, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return Outcome{}, err
	}
	defer tx.Rollback()

	now := s.nowTime()
	row, err := readRow(tx, resourceID)
	if errors.Is(err, sql.ErrNoRows) {
		return Outcome{}, ErrResourceNotFound
	}
	if err != nil {
		return Outcome{}, err
	}

	if row.hasOwner() && row.isExpired(now) && row.ownerID.String == ownerID {
		if err := promoteExpired(tx, resourceID, row, now); err != nil {
			return Outcome{}, err
		}
		if err := tx.Commit(); err != nil {
			return Outcome{}, err
		}
		return Outcome{}, ErrLeaseExpired
	}
	if !row.hasOwner() || row.ownerID.String != ownerID {
		if row.expiredOwnerID.Valid && row.expiredOwnerID.String == ownerID {
			return Outcome{}, ErrLeaseExpired
		}
		return Outcome{}, ErrNotOwner
	}

	if _, err := tx.Exec(
		`UPDATE resources SET reentry_count = reentry_count + 1 WHERE resource_id = ?`,
		resourceID,
	); err != nil {
		return Outcome{}, err
	}
	if err := tx.Commit(); err != nil {
		return Outcome{}, err
	}
	state, err := s.getStateLocked(resourceID)
	if err != nil {
		return Outcome{}, err
	}
	return Outcome{Status: StatusReentry, State: state}, nil
}
package store

import (
	"database/sql"
	"time"
)

// promoteExpired performs the deterministic transfer after a lease ran out.
//
// When a waiter exists, the first queued request becomes the new holder using the
// lease seconds it requested when it entered the queue, and is removed from the
// queue. With no waiter the resource returns to holderless state. The former owner
// is remembered so its late release/reentry keeps returning LEASE_EXPIRED even
// after a new holder took over.
func promoteExpired(tx *sql.Tx, resourceID string, row resourceRow, now time.Time) error {
	if !row.hasOwner() {
		return nil
	}

	var nextOwner string
	var nextLeaseSeconds int64
	var nextID int64
	err := tx.QueryRow(
		`SELECT id, owner_id, lease_seconds FROM waiting_requests
		 WHERE resource_id = ? ORDER BY id LIMIT 1`, resourceID,
	).Scan(&nextID, &nextOwner, &nextLeaseSeconds)
	if err == sql.ErrNoRows {
		_, err = tx.Exec(
			`UPDATE resources
			 SET owner_id = NULL, lease_expires_at = NULL, reentry_count = 0,
			     expired_owner_id = ?
			 WHERE resource_id = ?`,
			row.ownerID.String, resourceID,
		)
		return err
	}
	if err != nil {
		return err
	}

	if _, err := tx.Exec(
		`UPDATE resources
		 SET owner_id = ?, lease_expires_at = ?, reentry_count = 1,
		     expired_owner_id = ?
		 WHERE resource_id = ?`,
		nextOwner, now.Add(time.Duration(nextLeaseSeconds)*time.Second).UnixMilli(),
		row.ownerID.String, resourceID,
	); err != nil {
		return err
	}
	_, err = tx.Exec(`DELETE FROM waiting_requests WHERE id = ?`, nextID)
	return err
}

// promoteVoluntary transfers the lock because the current holder released it while
// its lease was still valid. No former-owner marker is recorded.
func promoteVoluntary(tx *sql.Tx, resourceID string, now time.Time) error {
	var nextOwner string
	var nextLeaseSeconds int64
	var nextID int64
	err := tx.QueryRow(
		`SELECT id, owner_id, lease_seconds FROM waiting_requests
		 WHERE resource_id = ? ORDER BY id LIMIT 1`, resourceID,
	).Scan(&nextID, &nextOwner, &nextLeaseSeconds)
	if err == sql.ErrNoRows {
		_, err = tx.Exec(
			`UPDATE resources
			 SET owner_id = NULL, lease_expires_at = NULL, reentry_count = 0
			 WHERE resource_id = ?`,
			resourceID,
		)
		return err
	}
	if err != nil {
		return err
	}

	if _, err := tx.Exec(
		`UPDATE resources
		 SET owner_id = ?, lease_expires_at = ?, reentry_count = 1
		 WHERE resource_id = ?`,
		nextOwner, now.Add(time.Duration(nextLeaseSeconds)*time.Second).UnixMilli(),
		resourceID,
	); err != nil {
		return err
	}
	_, err = tx.Exec(`DELETE FROM waiting_requests WHERE id = ?`, nextID)
	return err
}
package store

import (
	"database/sql"
	"errors"
	"time"
)

// Acquire grants the lock, records a same-owner reentry, or enqueues a waiter.
//
// leaseSeconds is the duration the caller wants once the lock is effective; waiters
// keep their own requested duration until promotion.
func (s *Store) Acquire(resourceID, ownerID string, leaseSeconds int64) (Outcome, error) {
	if leaseSeconds <= 0 {
		return Outcome{}, ErrInvalidLeaseSecond
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return Outcome{}, err
	}
	defer tx.Rollback()

	now := s.nowTime()
	row, err := readRow(tx, resourceID)
	status := StatusAcquired
	if errors.Is(err, sql.ErrNoRows) {
		if _, err := tx.Exec(
			`INSERT INTO resources(resource_id, owner_id, lease_expires_at, reentry_count, expired_owner_id)
			 VALUES(?, ?, ?, 1, NULL)`,
			resourceID, ownerID, now.Add(time.Duration(leaseSeconds)*time.Second).UnixMilli(),
		); err != nil {
			return Outcome{}, err
		}
	} else if err != nil {
		return Outcome{}, err
	} else {
		if row.hasOwner() && row.isExpired(now) {
			if row.ownerID.String == ownerID {
				if err := promoteExpired(tx, resourceID, row, now); err != nil {
					return Outcome{}, err
				}
				if err := tx.Commit(); err != nil {
					return Outcome{}, err
				}
				return Outcome{}, ErrLeaseExpired
			}
			if err := promoteExpired(tx, resourceID, row, now); err != nil {
				return Outcome{}, err
			}
			if row, err = readRow(tx, resourceID); err != nil {
				return Outcome{}, err
			}
		}
		switch {
		case !row.hasOwner():
			if _, err := tx.Exec(
				`UPDATE resources
				 SET owner_id = ?, lease_expires_at = ?, reentry_count = 1,
				     expired_owner_id = CASE WHEN expired_owner_id = ? THEN NULL ELSE expired_owner_id END
				 WHERE resource_id = ?`,
				ownerID, now.Add(time.Duration(leaseSeconds)*time.Second).UnixMilli(),
				ownerID, resourceID,
			); err != nil {
				return Outcome{}, err
			}
		case row.ownerID.String == ownerID:
			if _, err := tx.Exec(
				`UPDATE resources SET reentry_count = reentry_count + 1 WHERE resource_id = ?`,
				resourceID,
			); err != nil {
				return Outcome{}, err
			}
			status = StatusReentry
		default:
			dup, err := isWaiting(tx, resourceID, ownerID)
			if err != nil {
				return Outcome{}, err
			}
			if dup {
				if err := tx.Commit(); err != nil {
					return Outcome{}, err
				}
				state, err := s.getStateLocked(resourceID)
				if err != nil {
					return Outcome{}, err
				}
				return Outcome{Status: StatusWaiting, State: state}, ErrDuplicateWaiting
			}
			if _, err := tx.Exec(
				`INSERT INTO waiting_requests(resource_id, owner_id, lease_seconds) VALUES(?, ?, ?)`,
				resourceID, ownerID, leaseSeconds,
			); err != nil {
				return Outcome{}, err
			}
			if row.expiredOwnerID.Valid && row.expiredOwnerID.String == ownerID {
				if _, err := tx.Exec(
					`UPDATE resources SET expired_owner_id = NULL WHERE resource_id = ?`, resourceID,
				); err != nil {
					return Outcome{}, err
				}
			}
			if err := tx.Commit(); err != nil {
				return Outcome{}, err
			}
			state, err := s.getStateLocked(resourceID)
			if err != nil {
				return Outcome{}, err
			}
			return Outcome{Status: StatusWaiting, State: state}, nil
		}
	}

	if err := tx.Commit(); err != nil {
		return Outcome{}, err
	}
	state, err := s.getStateLocked(resourceID)
	if err != nil {
		return Outcome{}, err
	}
	return Outcome{Status: status, State: state}, nil
}

